/**
 * @suppress
 */
public object FfiConverterTypeKtListener: FfiConverter<KtListener, Long> {
    internal val handleMap = UniffiHandleMap<KtListener>()

    override fun lower(value: KtListener): Long {
        if (value is KtListenerImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): KtListener {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return KtListenerImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): KtListener {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: KtListener) = 8UL

    override fun write(value: KtListener, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


