     * the old setting) removed.
     */
    fun `setBackupPassword`(`password`: kotlin.String?)
    
    /**
     * Phones report Wi-Fi, charging, and whether the phone is constrained (battery saver,
     * low battery, heat, data saver); the node knows when the app is open. Helping others
     * follows them (§7a).
     */
    fun `setDeviceState`(`onWifi`: kotlin.Boolean, `charging`: kotlin.Boolean, `constrained`: kotlin.Boolean)
    
    fun `setDisplayName`(`name`: kotlin.String)
    
    fun `setDone`(`listId`: kotlin.String, `taskId`: kotlin.String, `done`: kotlin.Boolean)
    
    /**
     * Set a list's color and icon (shared with everyone in the list's group).
     */
    fun `setListStyle`(`listId`: kotlin.String, `hue`: kotlin.Double?, `vivid`: kotlin.UByte, `icon`: kotlin.String?)
    
    /**
     * "tasks" or "shopping" for everyone in the list.
     */
    fun `setListType`(`listId`: kotlin.String, `listType`: kotlin.String)
    
    fun `setListener`(`listener`: KtListener)
    
    /**
